-- V22: Java V1 curriculum — 80 gold-standard learning units
-- Java V1 covers Foundations, OOP, Collections, Modern Java, Exceptions/I/O,
-- Testing/Tools, JVM/Performance, and an applied Interview Lab.
-- Content is intentionally independent from the DSA problem schema so the same
-- mastery/revision engine can be wired to Java lessons in a later API/UI batch.

CREATE TABLE IF NOT EXISTS java_tracks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug VARCHAR(100) NOT NULL UNIQUE,
    title VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    version VARCHAR(20) NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'READY',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS java_modules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    track_id UUID NOT NULL REFERENCES java_tracks(id) ON DELETE CASCADE,
    module_order INT NOT NULL,
    slug VARCHAR(100) NOT NULL,
    title VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    UNIQUE(track_id, slug),
    UNIQUE(track_id, module_order)
);

CREATE TABLE IF NOT EXISTS java_lessons (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    module_id UUID NOT NULL REFERENCES java_modules(id) ON DELETE CASCADE,
    lesson_order INT NOT NULL,
    slug VARCHAR(160) NOT NULL,
    title VARCHAR(250) NOT NULL,
    lesson_type VARCHAR(40) NOT NULL DEFAULT 'LEARN',
    difficulty VARCHAR(30) NOT NULL DEFAULT 'FOUNDATION',
    concept TEXT NOT NULL,
    learning_objectives TEXT NOT NULL,
    practice_prompt TEXT NOT NULL,
    interview_focus TEXT NOT NULL,
    content_status VARCHAR(30) NOT NULL DEFAULT 'CONTENT_REVIEW',
    UNIQUE(module_id, slug),
    UNIQUE(module_id, lesson_order)
);

